    32  v_buff_size Utils::calcEscapedStringSize(const char* data, v_buff_size size, v_buff_size& safeSize, v_uint32 flags) {
    33    v_buff_size result = 0;
    34    v_buff_size i = 0;
    35    safeSize = size;
    36    while (i < size) {
    37      v_char8 a = static_cast<v_char8>(data[i]);
    38      if(a < 32) {
    39        i ++;
    40
    41        switch (a) {
    42
    43          case '\b':
    44          case '\f':
    45          case '\n':
    46          case '\r':
    47          case '\t': result += 2; break; // '\n'
    48
    49          default:
    50            result += 6; // '\uFFFF' - 6 chars
    51            break;
    52
    53        }
    54
    55      } else if(a < 128){
    56        i ++;
    57
    58        switch (a) {
    59          case '\"':
    60          case '\\': result += 2; break; // '\/'
    61
    62          case '/':
    63            result ++;
    64            if((flags & FLAG_ESCAPE_SOLIDUS) > 0) result ++;
    65            break;
    66
    67          default:
    68            result ++;
    69            break;
    70
    71        }
    72
    73      } else {
    74        v_buff_size charSize = oatpp::encoding::Unicode::getUtf8CharSequenceLength(a);
    75        if(charSize != 0) {
    76          if(i + charSize > size) {
    77            safeSize = i;
    78          }
    79          i += charSize;
    80          if (!(flags & FLAG_ESCAPE_UTF8CHAR)) {
    81            result += charSize; // output as-is
    82          } else if(charSize < 4) {
    83            result += 6; // '\uFFFF' - 6 chars
    84          } else if(charSize == 4) {
    85            result += 12; // '\uFFFF\uFFFF' - 12 chars surrogate pair
    86          } else {
    87            result += 11; // '\u+FFFFFFFF' - 11 chars NOT JSON standard case
    88          }
    89        } else {
    90          // invalid char
    91          i ++;
    92          result ++;
    93        }
    94      }
    95    }
    96    return result;
    97  }
