    99  v_buff_size Utils::calcUnescapedStringSize(const char* data, v_buff_size size, v_int64& errorCode, v_buff_size& errorPosition) {
   100    errorCode = 0;
   101    v_buff_size result = 0;
   102    v_buff_size i = 0;
   103
   104    while (i < size) {
   105      v_char8 a = static_cast<v_char8>(data[i]);
   106      if(a == '\\'){
   107
   108        if(i + 1 == size){
   109          errorCode = ERROR_CODE_INVALID_ESCAPED_CHAR;
   110          errorPosition = i;
   111          return 0;
   112        }
   113
   114        v_char8 b = static_cast<v_char8>(data[i + 1]);
   115
   116        if(b == '"' || b == '\\' || b == '/' || b == 'b' || b == 'f' || b == 'n' || b == 'r' || b == 't'){
   117          result += 1;
   118          i += 2;
   119        } else if(b == 'u'){
   120
   121          if(i + 6 > size){
   122            errorCode = ERROR_CODE_INVALID_ESCAPED_CHAR;
   123            errorPosition = i;
   124            return 0;
   125          }
