    61  v_buff_size Unicode::getUtf8CharSequenceLengthForCode(v_uint32 code){
    62    if(code < 128) {
    63      return 1;
    64    } else if(code < 0x00000800){
    65      return 2;
    66    } else if(code < 0x00010000){
    67      return 3;
    68    } else if(code < 0x00200000){
    69      return 4;
    70    } else if(code < 0x04000000){
    71      return 5;
    72    } else {
    73      return 6;
    74    }
    75  }
