   372  oatpp::String Utils::unescapeString(const char* data, v_buff_size size, v_int64& errorCode, v_buff_size& errorPosition) {
   373
   374    v_buff_size unescapedSize = calcUnescapedStringSize(data, size, errorCode, errorPosition);
   375    if(errorCode != 0){
   376      return nullptr;
   377    }
   378    String result(unescapedSize);
   379    if(unescapedSize == size) {
   380      std::memcpy(reinterpret_cast<void*>(result->data()), data, static_cast<size_t>(size));
   381    } else {
   382      unescapeStringToBuffer(data, size, reinterpret_cast<p_char8>(result->data()));
   383    }
   384    return result;
   385
