   406
   407    if(caret.canContinueAtChar('"', 1)){
   408
   409      const char* data = caret.getData();
   410      v_buff_size pos = caret.getPosition();
   411      v_buff_size pos0 = pos;
   412      v_buff_size length = caret.getDataSize();
   413
   414      while (pos < length) {
   415        v_char8 a = static_cast<v_char8>(data[pos]);
   416        if(a == '"'){
   417          size = pos - pos0;
